SELECT  FROM crm_institution WHERE tenant_id=#{tenantId} AND archived=0

AND (institution_no LIKE CONCAT('%',#{keyword},'%') OR full_name LIKE CONCAT('%',#{keyword},'%') OR short_name LIKE CONCAT('%',#{keyword},'%'))

AND status=#{status}
AND city_code=#{cityCode}
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM crm_institution WHERE tenant_id=#{tenantId} AND archived=0

AND (institution_no LIKE CONCAT('%',#{keyword},'%') OR full_name LIKE CONCAT('%',#{keyword},'%') OR short_name LIKE CONCAT('%',#{keyword},'%'))

AND status=#{status}
AND city_code=#{cityCode}

