  ownership_code=#{value}
  grade_code=#{value}
  bank_name_cipher=#{value}
  bank_account_cipher=#{value}
  tax_id_cipher=#{value}
  settlement_name=#{value}
  online_rate=#{value}
  offline_rate=#{value}
  platform_rate=#{value}
  other_rate_rule=#{value}
  charges_fee=#{value}
  deposit_fen=#{value}
  guarantee_roi=#{value}
  roi_terms=#{value}
  settlement_type=#{value}
  version=version

,version=version+1 WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{version} AND archived=0

